'use strict';
// Cosmetics: one appearance slot layered over the selected Justin (outfit + effects + one ability).
// This file draws the outfits (through Justin's squash/rotation/dance and the iPhone image fallback),
// runs the Cosmetics shop, and owns the ability button. Activities live in abilities.js.
(()=>{
 const G=JustinGame,C=G.Cosmetics,game=window.justinClicker,el=id=>document.getElementById(id),stage=el('stage');
 const reduced=()=>el('gentle').checked||matchMedia('(prefers-reduced-motion: reduce)').matches;
 const serverNow=()=>window.justinOnline?.serverNow?.()||Date.now();
 const INK='#202020';
 let snap=game.snapshot(),wornId=null,tryOn=null,tryUntil=0;
 const mode={name:'idle',since:0};
 function setMode(name){mode.name=name;mode.since=performance.now()}
 const ready=()=>Boolean(snap.cosmetics?.equipped)&&C.abilityReady(snap,serverNow());

 /* ---------- hand-drawn outfit pieces (local face coordinates: u = face width, h = face height, origin = face centre) ---------- */
 function ink(c,u,w=.022){c.strokeStyle=INK;c.lineWidth=Math.max(1.5,u*w);c.lineJoin=c.lineCap='round'}
 function rr(c,x,y,w,h,r){c.beginPath();c.moveTo(x+r,y);c.arcTo(x+w,y,x+w,y+h,r);c.arcTo(x+w,y+h,x,y+h,r);c.arcTo(x,y+h,x,y,r);c.arcTo(x,y,x+w,y,r);c.closePath()}
 function clockFace(c,r,t,fast){c.fillStyle='#fff6d8';c.beginPath();c.arc(0,0,r,0,Math.PI*2);c.fill();c.stroke();for(let i=0;i<12;i++){const a=i/12*Math.PI*2;c.beginPath();c.moveTo(Math.cos(a)*r*.78,Math.sin(a)*r*.78);c.lineTo(Math.cos(a)*r*.9,Math.sin(a)*r*.9);c.stroke()}const m=t*(fast?9:.6),hr=t*(fast?.9:.05);c.beginPath();c.moveTo(0,0);c.lineTo(Math.sin(m)*r*.7,-Math.cos(m)*r*.7);c.moveTo(0,0);c.lineTo(Math.sin(hr)*r*.45,-Math.cos(hr)*r*.45);c.stroke()}
 function sparkle(c,x,y,s,col='#ffd400'){c.save();c.translate(x,y);c.fillStyle=col;c.beginPath();for(let i=0;i<8;i++){const r=i%2?s*.35:s,a=i/8*Math.PI*2;c.lineTo(Math.cos(a)*r,Math.sin(a)*r)}c.closePath();c.fill();c.restore()}
 const outfits={
  time:{behind(c,u,h,t,m){c.save();c.translate(u*.36,-h*.3);c.rotate(.3+(m.ready?Math.sin(t*7)*.07:0));ink(c,u);clockFace(c,u*.3,t,m.name==='active');c.restore()},
        front(c,u,h,t,m){c.save();c.translate(u*.42,h*.36);c.rotate(-.5);ink(c,u);c.fillStyle='#8b5a2b';rr(c,-u*.06,-u*.2,u*.12,u*.4,u*.03);c.fill();c.stroke();c.fillStyle='#ffd400';c.beginPath();c.arc(0,0,u*.12,0,Math.PI*2);c.fill();c.stroke();c.translate(0,0);clockFace(c,u*.085,t*1.7,m.name==='active');c.restore()}},
  case:{behind(c,u,h,t,m){c.save();const open=m.name==='active'?.55:m.ready?.12+Math.abs(Math.sin(t*5))*.08:.05;c.translate(0,h*.22);c.rotate(-open);ink(c,u);c.fillStyle='#5d6470';rr(c,-u*.62,-h*.5,u*1.24,h*.5,u*.08);c.fill();c.stroke();c.restore()},
        front(c,u,h,t,m){c.save();ink(c,u);c.fillStyle='#6e7581';rr(c,-u*.62,h*.2,u*1.24,h*.44,u*.08);c.fill();c.stroke();c.strokeStyle='#4f5560';c.lineWidth=u*.018;for(let i=1;i<5;i++){c.beginPath();c.moveTo(-u*.55,h*.2+i*h*.085);c.lineTo(u*.55,h*.2+i*h*.085);c.stroke()}ink(c,u);c.fillStyle='#3b4049';for(const [x,y] of [[-.62,.2],[.52,.2],[-.62,.56],[.52,.56]]){rr(c,x*u,y*h,u*.1,h*.08,u*.02);c.fill()}
         c.fillStyle='#ff5fb1';c.save();c.translate(-u*.25,h*.45);c.rotate(-.2);c.fillRect(-u*.12,-u*.05,u*.24,u*.1);c.fillStyle='#fff';c.font='bold '+Math.round(u*.06)+'px sans-serif';c.textAlign='center';c.fillText('FRAGILE',0,u*.02);c.restore();
         const swing=m.name==='active'?.9:m.ready?.6:.35;for(const [i,col] of [[0,'#ffd400'],[1,'#8dff6a']].entries()){c.save();c.translate(u*(.56),h*(.28+i*.06));c.rotate(Math.sin(t*3.2+i*1.7)*swing+.3);ink(c,u,.012);c.beginPath();c.moveTo(0,0);c.lineTo(0,u*.16);c.stroke();ink(c,u);c.fillStyle=col;rr(c,-u*.07,u*.16,u*.14,u*.2,u*.02);c.fill();c.stroke();c.restore()}c.restore()}},
  hero:{behind(c,u,h,t,m){c.save();ink(c,u);const flap=Math.sin(t*(m.name==='active'?9:3))*u*(m.name==='active'?.18:.08),wide=m.name==='active'?1.35:1;c.fillStyle='#e8344e';c.beginPath();c.moveTo(-u*.32,h*.26);c.lineTo(u*.32,h*.26);c.quadraticCurveTo(u*.8*wide+flap,h*.55,u*.7*wide+flap,h*.8);c.lineTo(-u*.7*wide+flap*.6,h*.82);c.quadraticCurveTo(-u*.82*wide,h*.55,-u*.32,h*.26);c.fill();c.stroke();c.strokeStyle='#b81f39';c.lineWidth=u*.02;for(const x of [-.25,.05,.3]){c.beginPath();c.moveTo(x*u,h*.32);c.lineTo(x*u*1.6+flap*.5,h*.78);c.stroke()}c.restore()},
        front(c,u,h,t,m){c.save();c.translate(u*.05,h*.52);c.rotate(-.25+(m.ready?Math.sin(t*6)*.08:0));ink(c,u);c.fillStyle='#ffd400';c.beginPath();c.moveTo(0,-u*.14);c.lineTo(u*.16,0);c.lineTo(0,u*.15);c.lineTo(-u*.15,0);c.closePath();c.fill();c.stroke();c.fillStyle='#e8344e';c.font='900 '+Math.round(u*.16)+'px sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText('J',u*.01,u*.01);c.restore()}},
  charge:{behind(c,u,h,t,m){c.save();ink(c,u);c.strokeStyle='#333';c.lineWidth=u*.03;c.beginPath();c.moveTo(-u*.55,-h*.02);c.bezierCurveTo(-u*.1,-h*.6,u*.2,-h*.1,-u*.05,-h*.42);c.moveTo(-u*.5,h*.15);c.bezierCurveTo(-u*.9,h*.3,u*.1,h*.5,-u*.2,h*.3);c.stroke();c.translate(-u*.66,h*.12);c.rotate(-.15);ink(c,u);c.fillStyle='#7ae04a';rr(c,-u*.16,-h*.22,u*.32,h*.44,u*.04);c.fill();c.stroke();c.fillStyle='#202020';c.fillRect(-u*.06,-h*.26,u*.12,h*.04);const level=m.name==='finish'?.1:m.ready?1:.6;c.fillStyle='#ffd400';for(let i=0;i<4;i++)if(i<level*4){c.fillRect(-u*.1,h*.15-i*h*.09,u*.2,h*.06)}c.restore()},
        front(c,u,h,t,m){if(reduced())return;const tick=Math.floor(t*(m.name==='active'?16:7));c.save();ink(c,u,.014);c.strokeStyle='#ffd400';for(let i=0;i<(m.ready||m.name==='active'?3:1);i++){const seed=(tick*31+i*17)%97/97,x=(-.7+seed*.5)*u,y=(-.3+((seed*7)%1)*.6)*h;c.beginPath();c.moveTo(x,y);c.lineTo(x+u*.05,y+u*.04);c.lineTo(x+u*.02,y+u*.07);c.lineTo(x+u*.08,y+u*.11);c.stroke()}c.restore()}},
  debt:{behind(c,u,h,t,m){},
        front(c,u,h,t,m){c.save();ink(c,u);c.save();c.translate(0,h*.31);c.rotate(.28+Math.sin(t*2)*.04);c.fillStyle='#c8102e';c.beginPath();c.moveTo(-u*.05,0);c.lineTo(u*.05,0);c.lineTo(u*.03,u*.06);c.lineTo(-u*.03,u*.06);c.closePath();c.fill();c.stroke();c.beginPath();c.moveTo(-u*.03,u*.06);c.lineTo(u*.03,u*.06);c.lineTo(u*.07,u*.42);c.lineTo(0,u*.5);c.lineTo(-u*.06,u*.42);c.closePath();c.fill();c.stroke();c.restore();
         c.save();c.translate(-u*.5,h*.42);c.rotate(.2);c.fillStyle='#fff';for(let i=0;i<4;i++){const lift=m.name==='active'?Math.sin(t*6+i)*u*.05:0;c.save();c.rotate(-.3+i*.18);rr(c,-u*.07,-u*.26-lift,u*.14,u*.2,u*.01);c.fill();c.stroke();c.restore()}c.fillStyle='#c98a4b';rr(c,-u*.17,-u*.1,u*.34,u*.24,u*.03);c.fill();c.stroke();c.restore();
         const tx=Math.sin(t*.7)*u*.45;c.translate(tx,h*.66);c.scale(Math.cos(t*.7)>0?1:-1,1);ink(c,u,.014);c.fillStyle='#ffd400';rr(c,-u*.12,-u*.07,u*.14,u*.07,u*.01);c.fill();c.stroke();c.fillStyle='#9fe9ff';rr(c,u*.02,-u*.07,u*.06,u*.07,u*.01);c.fill();c.stroke();c.fillStyle=INK;for(const x of [-.08,.05]){c.beginPath();c.arc(x*u,0,u*.022,0,Math.PI*2);c.fill()}c.beginPath();c.moveTo(-u*.12,-u*.06);c.lineTo(-u*.18,-u*.12);c.lineTo(-u*.2,-u*.04);c.stroke();c.restore()}},
  trouble:{behind(c,u,h,t,m){c.save();c.translate(-u*.66,-h*.2);c.rotate(-.12);const unfold=m.ready||m.name==='active'?1:.85+Math.sin(t*1.3)*.15;c.scale(1,unfold);ink(c,u);c.fillStyle='#f3e2b3';rr(c,-u*.2,-u*.27,u*.4,u*.54,u*.02);c.fill();c.stroke();c.fillStyle=INK;c.font='900 '+Math.round(u*.075)+'px sans-serif';c.textAlign='center';c.fillText('WANTED',0,-u*.17);c.beginPath();c.arc(0,u*.02,u*.1,0,Math.PI*2);c.stroke();c.font='bold '+Math.round(u*.05)+'px sans-serif';c.fillText('for clicking',0,u*.2);c.restore()},
        front(c,u,h,t,m){c.save();ink(c,u);c.fillStyle='#b08850';for(const side of [-1,1]){c.beginPath();c.moveTo(side*u*.5,h*.27);c.lineTo(side*u*.08,h*.32);c.lineTo(side*u*.02,h*.62);c.lineTo(side*u*.55,h*.62);c.closePath();c.fill();c.stroke()}
         c.translate(u*.06,h*.13);c.rotate(.16);const peel=m.name==='active'?.5:Math.max(0,Math.sin(t*1.1))*.25;c.fillStyle='#3a2414';c.beginPath();c.moveTo(-u*.17,u*.02);c.quadraticCurveTo(-u*.09,-u*.05,0,0);c.quadraticCurveTo(u*.09,-u*.05,u*.17,u*.02-peel*u*.15);c.quadraticCurveTo(u*.08,u*.04,0,u*.025);c.quadraticCurveTo(-u*.08,u*.05,-u*.17,u*.02);c.fill();c.restore()}}
 };
 function decorate(layer,c,size,ht,id=wornId){const o=outfits[id];if(!o)return;const t=performance.now()/1000,m={name:mode.name,ready:mode.name==='idle'&&ready()};c.save();c.filter='none';c.imageSmoothingEnabled=true;try{o[layer](c,size,ht,reduced()?0:t,m)}finally{c.restore()}if(layer==='front'&&m.ready&&!reduced()){const k=(t*2)%1;sparkle(c,size*.5*Math.cos(t),-ht*.42,size*.04*(1-k),'#ffd400')}}
 // iPhone fallback: the face is an <img> above the canvas, so front pieces go on a small overlay canvas instead.
 const overlayCanvas=document.createElement('canvas');overlayCanvas.className='cosmetic-overlay';overlayCanvas.setAttribute('aria-hidden','true');stage.append(overlayCanvas);const octx=overlayCanvas.getContext('2d');let overlayDirty=false;
 const safeMode=()=>el('safe-face')?.checked;
 window.JustinCosmetic={
  behind:(c,size,ht)=>decorate('behind',c,size,ht),
  front:(c,size,ht)=>{if(!safeMode())decorate('front',c,size,ht)},
  overlay(x,y,size,rot,sx,sy,m){if(!safeMode()||!wornId){if(overlayDirty){octx.clearRect(0,0,overlayCanvas.width,overlayCanvas.height);overlayDirty=false}return}const r=stage.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,1.5);if(overlayCanvas.width!==Math.round(r.width*d)){overlayCanvas.width=Math.round(r.width*d);overlayCanvas.height=Math.round(r.height*d)}octx.setTransform(d,0,0,d,0,0);octx.clearRect(0,0,r.width,r.height);octx.translate(x,y);if(m)octx.transform(m[0],m[1],m[2],m[3],0,0);octx.rotate(rot);octx.scale(sx,sy);decorate('front',octx,size,size*1280/820);overlayDirty=true},
  setMode,draw:decorate,worn:()=>wornId,
  tryOn(id,ms=20000){tryOn=id;tryUntil=performance.now()+ms;refresh()},
  stopTryOn(){tryOn=null;refresh()}
 };

 /* ---------- shop ---------- */
 const dockButton=document.createElement('button');dockButton.id='cosmetics-open';dockButton.type='button';dockButton.className='cosmetics-feature';dockButton.innerHTML='<img class="ui-icon" src="assets/icons/star.svg" alt=""><span><b>Cosmetics</b><small>Outfits with abilities</small></span>';el('backdrops-open').after(dockButton);
 const dialog=document.createElement('dialog');dialog.className='online-dialog cosmetics-dialog';dialog.setAttribute('aria-label','Cosmetics shop');
 dialog.innerHTML='<div class="online-dialog-head"><div><small>ONE OUTFIT AT A TIME · WORKS WITH ANY JUSTIN</small><h2>Cosmetics</h2></div><button type="button" class="icon-close" aria-label="Close cosmetics"><img class="ui-icon" src="assets/icons/close.svg" alt=""></button></div><div class="cos-wallet">wallet · <b id="cos-wallet"></b></div><div class="cos-layout"><div class="cos-grid" id="cos-grid"></div><aside class="cos-preview" aria-live="polite"><canvas id="cos-preview-canvas" width="300" height="340" aria-hidden="true"></canvas><b id="cos-name"></b><span id="cos-ability"></span><p id="cos-desc"></p><div class="cos-actions"><button type="button" id="cos-try">Try on</button><button type="button" id="cos-demo">Preview ability</button><button type="button" id="cos-main"></button></div><small id="cos-note"></small></aside></div>';
 document.body.append(dialog);dialog.querySelector('.icon-close').onclick=()=>dialog.close();
 let selected=C.cosmetics[0].id;const cards=new Map(),fmt=n=>n>=1e6?(n/1e6).toFixed(n%1e6?1:0)+'M':n>=1e3?Math.round(n/1e3)+'K':String(n);
 for(const c of C.cosmetics){const card=document.createElement('button');card.type='button';card.className='cos-card';card.dataset.id=c.id;card.innerHTML='<canvas width="150" height="170" aria-hidden="true"></canvas><b></b><em></em><small></small><span class="cos-ribbon" hidden>EQUIPPED</span>';card.querySelector('b').textContent=c.name;card.querySelector('small').textContent=c.ability;card.onclick=()=>{selected=c.id;refresh()};el('cos-grid').append(card);cards.set(c.id,card)}
 function drawJustin(canvas,id){const c=canvas.getContext('2d'),W=canvas.width,H=canvas.height,skin=game.skin||G.skins[0],img=window.JustinSprites?.animated?.(skin)||window.JustinSprites?.get(skin);c.clearRect(0,0,W,H);const size=Math.min(W*.5,H*.42),ht=size*1280/820;c.save();c.translate(W/2,H*.47);const t=performance.now()/1000;if(!reduced())c.rotate(Math.sin(t*1.6)*.04);decorate('behind',c,size,ht,id);if(img)c.drawImage(img,-size/2,-ht/2,size,ht);decorate('front',c,size,ht,id);c.restore()}
 function refresh(){snap=game.snapshot();const owned=snap.cosmetics?.owned||[],equipped=snap.cosmetics?.equipped||null;wornId=tryOn&&performance.now()<tryUntil?tryOn:equipped;if(!dialog.open)return;el('cos-wallet').textContent=Math.floor(snap.bank).toLocaleString()+' points';
  for(const c of C.cosmetics){const card=cards.get(c.id),own=owned.includes(c.id);card.classList.toggle('is-selected',c.id===selected);card.classList.toggle('is-owned',own);card.querySelector('.cos-ribbon').hidden=equipped!==c.id;card.querySelector('em').textContent=own?(equipped===c.id?'wearing':'owned'):fmt(c.cost)+' pts';card.classList.toggle('can-afford',!own&&snap.bank>=c.cost)}
  const c=C.byId(selected),own=owned.includes(c.id),busy=Boolean(snap.ability?.active);el('cos-name').textContent=c.name;el('cos-ability').textContent='Ability: '+c.ability;el('cos-desc').textContent=c.desc;const main=el('cos-main');
  main.textContent=equipped===c.id?'Unequip':own?'Equip':'Buy · '+c.cost.toLocaleString();main.disabled=busy||(!own&&snap.bank<c.cost)||(game.ranked()&&!window.justinOnline.connected());main.dataset.kind=equipped===c.id?'unequip':own?'equip':'buy';
  el('cos-try').textContent=tryOn===c.id&&performance.now()<tryUntil?'Stop trying on':'Try on';el('cos-demo').disabled=Boolean(window.JustinAbilities?.running());
  el('cos-note').textContent=busy?'An ability is running. Change outfits when it ends.':!own&&snap.bank<c.cost?'You need '+Math.ceil(c.cost-snap.bank).toLocaleString()+' more points.':'Cooldown is shared: switching outfits keeps your charge.'}
 el('cos-main').onclick=()=>{const kind=el('cos-main').dataset.kind;if(kind==='buy'){game.featureAction('cosmetic-buy',{id:selected});window.JustinGUIAudio?.play('buy');tryOn=null}else game.featureAction('cosmetic-equip',{id:kind==='unequip'?null:selected});setTimeout(refresh,60)};
 el('cos-try').onclick=()=>{if(tryOn===selected&&performance.now()<tryUntil){tryOn=null}else{tryOn=selected;tryUntil=performance.now()+20000;dialog.close();window.JustinJuice?.say('how do I look?',{force:true})}refresh()};
 el('cos-demo').onclick=()=>{dialog.close();setTimeout(()=>window.JustinAbilities?.activate(selected,{demo:true}),250)};
 dockButton.onclick=()=>{const eq=game.snapshot().cosmetics?.equipped;if(eq)selected=eq;dialog.showModal();refresh()};
 let shopAt=0;function shopFrame(ms){if(!dialog.open)return;requestAnimationFrame(shopFrame);if(ms-shopAt<(reduced()?400:45))return;shopAt=ms;for(const [id,card] of cards)drawJustin(card.querySelector('canvas'),id);drawJustin(el('cos-preview-canvas'),selected)}
 dialog.addEventListener('toggle',()=>{if(dialog.open)requestAnimationFrame(shopFrame)});new MutationObserver(()=>{if(dialog.open)requestAnimationFrame(shopFrame)}).observe(dialog,{attributes:true,attributeFilter:['open']});

 /* ---------- ability button under Justin ---------- */
 const dock=document.createElement('div');dock.id='ability-dock';dock.hidden=true;dock.innerHTML='<button type="button" id="ability-button"><svg viewBox="0 0 44 44" aria-hidden="true"><circle cx="22" cy="22" r="19" class="ring-bg"/><circle cx="22" cy="22" r="19" class="ring" pathLength="100"/></svg><canvas width="64" height="64" aria-hidden="true"></canvas><span><b></b><small></small></span></button>';
 stage.after(dock);const abilityButton=el('ability-button'),ring=dock.querySelector('.ring'),iconCanvas=dock.querySelector('canvas');let iconFor='';
 function updateButton(){const id=snap.cosmetics?.equipped||null;dock.hidden=!id;if(!id)return;const c=C.byId(id),at=serverNow(),readyAt=snap.ability?.readyAt||0,left=Math.max(0,readyAt-at),running=window.JustinAbilities?.running()||Boolean(snap.ability?.active),blocked=!running&&!left&&C.invasionBusy(snap,at);
  const state=running?'running':blocked?'blocked':left>0?'cooldown':'ready';abilityButton.dataset.state=state;ring.style.strokeDashoffset=String(state==='cooldown'?Math.round(left/C.abilityCooldown*100):0);
  abilityButton.querySelector('b').textContent=c.ability;abilityButton.querySelector('small').textContent=state==='ready'?'Ready · tap to start':state==='running'?'Running…':state==='blocked'?'After the invasion · charge saved':Math.floor(left/60000)+':'+String(Math.ceil(left/1000)%60).padStart(2,'0');abilityButton.disabled=state!=='ready';abilityButton.setAttribute('aria-label',c.ability+' ability: '+abilityButton.querySelector('small').textContent);
  if(iconFor!==id+(game.skin?.id||'')){iconFor=id+(game.skin?.id||'');const c2=iconCanvas.getContext('2d');c2.clearRect(0,0,64,64);c2.save();c2.translate(32,30);decorate('behind',c2,30,47,id);const skin=game.skin||G.skins[0],img=window.JustinSprites?.get(skin);if(img)c2.drawImage(img,-15,-23.5,30,47);decorate('front',c2,30,47,id);c2.restore()}}
 abilityButton.onclick=()=>window.JustinAbilities?.activate(snap.cosmetics?.equipped,{demo:false});
 setInterval(()=>{if(document.hidden)return;refresh();updateButton()},250);refresh();updateButton();
})();
